import sys

def main():
    data = sys.stdin.read().split()
    n, c = int(data[0]), int(data[1])
    pos = sorted(int(x) for x in data[2:2 + n])
    lo, hi = 1, (pos[-1] - pos[0]) // (c - 1)
    while lo < hi:
        mid = (lo + hi + 1) // 2
        cnt, last = 1, pos[0]
        for p in pos:
            if p - last >= mid:
                cnt += 1
                last = p
                if cnt >= c:
                    break
        if cnt >= c:
            lo = mid
        else:
            hi = mid - 1
    print(lo)

