def gen(rng):
    def fmt(c, ps):
        return f"{len(ps)} {c}\n" + ' '.join(map(str, ps))
    tests = [fmt(2, [0, 1]), fmt(2, [1000000000, 0]), fmt(3, [0, 1, 2]), fmt(2, [5, 100, 7, 3]),
             fmt(4, [10, 0, 3, 6]), fmt(3, [2, 15, 4, 9, 20, 11])]
    for n in (3, 4, 5, 6, 8, 10, 12):
        for _ in range(3):
            c = rng.randint(2, n)
            tests.append(fmt(c, rng.sample(range(0, 60), n)))
    for _ in range(3):
        n = rng.randint(5, 12)
        c = rng.randint(2, 4)
        tests.append(fmt(c, rng.sample(range(0, 10**9 + 1), n)))
    n = 100000
    tests.append(fmt(2, rng.sample(range(0, 10**9 + 1), n)))
    tests.append(fmt(n, rng.sample(range(0, 10**9 + 1), n)))
    tests.append(fmt(n // 2, rng.sample(range(0, 10**9 + 1), n)))
    tests.append(fmt(1000, rng.sample(range(0, 10**9 + 1), n)))
    tests.append(fmt(50000, list(range(0, 10**9, 10**4))[:n]))
    return tests

